#!/usr/bin/env python3
"""Harvest public, geolocated KartaView street-level photos around the Manila district."""
from __future__ import annotations
import json, math, re, time
from pathlib import Path
import requests

ROOT = Path("StandaloneBattleRoyale/Content/Maps/Street-Imagery")
ROOT.mkdir(parents=True, exist_ok=True)
MANIFEST = ROOT / "manifest.json"
# Match the district generated by build_manila_district.py.
S, W, N, E = 14.575, 120.965, 14.600, 120.990
API = "https://api.openstreetcam.org/1.0/list/nearby-photos/"
SESSION = requests.Session()
SESSION.headers.update({"User-Agent": "AdamRoyal-ResearchGame/1.0 (public imagery research)"})
MAX_PHOTOS = 180
RADIUS_METERS = 350
# A coarse grid samples different streets, not merely different camera headings.
LAT_STEPS, LON_STEPS = 6, 6
seen = set()
items = []

def walk(obj):
    if isinstance(obj, dict):
        yield obj
        for value in obj.values():
            yield from walk(value)
    elif isinstance(obj, list):
        for value in obj:
            yield from walk(value)

def pick(record, *names):
    for name in names:
        value = record.get(name)
        if value not in (None, ""):
            return value
    return None

def photo_url(record):
    value = pick(record, "fileUrl", "fileurl", "photoUrl", "photo_url", "url", "thumbUrl", "thumburl")
    if isinstance(value, str) and value.startswith("http"):
        return value
    # Older responses sometimes return the image filename separately.
    filename = pick(record, "fileName", "filename", "name")
    if isinstance(filename, str) and filename.startswith("http"):
        return filename
    return None

def main():
    for iy in range(LAT_STEPS):
        lat = S + (N-S) * (iy + 0.5) / LAT_STEPS
        for ix in range(LON_STEPS):
            if len(items) >= MAX_PHOTOS:
                break
            lon = W + (E-W) * (ix + 0.5) / LON_STEPS
            try:
                response = SESSION.post(API, data={"lat": lat, "lng": lon, "radius": RADIUS_METERS}, timeout=35)
                response.raise_for_status()
                payload = response.json()
                records = list(walk(payload))
                for record in records:
                    url = photo_url(record)
                    if not url or url in seen:
                        continue
                    # Avoid downloading unrelated metadata objects that happen to contain URLs.
                    if not any(key in record for key in ("id", "photoId", "photo_id", "sequenceId", "sequence_id")):
                        continue
                    seen.add(url)
                    try:
                        image = SESSION.get(url, timeout=45)
                        image.raise_for_status()
                        ctype = image.headers.get("content-type", "").lower()
                        if not ctype.startswith("image/") or len(image.content) < 12_000:
                            continue
                        ext = ".png" if "png" in ctype else ".webp" if "webp" in ctype else ".jpg"
                        photo_id = str(pick(record, "id", "photoId", "photo_id") or len(items)+1)
                        safe_id = re.sub(r"[^A-Za-z0-9_-]", "_", photo_id)[:60]
                        name = f"kartaview_{len(items)+1:04d}_{safe_id}{ext}"
                        (ROOT / name).write_bytes(image.content)
                        items.append({
                            "file": name,
                            "source": "KartaView / OpenStreetCam public API",
                            "source_url": url,
                            "photo_id": pick(record, "id", "photoId", "photo_id"),
                            "sequence_id": pick(record, "sequenceId", "sequence_id"),
                            "latitude": pick(record, "lat", "latitude"),
                            "longitude": pick(record, "lng", "lon", "longitude"),
                            "heading": pick(record, "heading", "direction"),
                            "captured_at": pick(record, "dateAdded", "capturedAt", "date"),
                            "license_note": "Check source attribution and CC BY-SA terms before redistribution.",
                            "status": "street_reference_photo_not_yet_projected_onto_3d_mesh"
                        })
                        print(f"Saved {name} ({len(items)}/{MAX_PHOTOS})")
                        if len(items) >= MAX_PHOTOS:
                            break
                    except Exception as exc:
                        print(f"Skipping image {url}: {exc}")
                time.sleep(0.25)
            except Exception as exc:
                print(f"KartaView query skipped at {lat:.6f},{lon:.6f}: {exc}")
        if len(items) >= MAX_PHOTOS:
            break
    MANIFEST.write_text(json.dumps({
        "source": "KartaView public street-level imagery API",
        "district": {"south": S, "west": W, "north": N, "east": E},
        "query_grid": {"latitude_steps": LAT_STEPS, "longitude_steps": LON_STEPS, "radius_meters": RADIUS_METERS},
        "downloaded_photos": len(items),
        "important_limit": "These are geolocated reference photos. This script does not claim they are projected onto buildings or used as in-game textures.",
        "images": items
    }, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"KartaView complete: {len(items)} images saved to {ROOT}")
    # No imagery coverage is not a map-generation failure; manifest records the result.
if __name__ == "__main__":
    main()
